// Updated: 对齐 GB/T 31917-2015 标准键盘布局
package com.example.kyrgyzkeyboard.utils

import com.example.kyrgyzkeyboard.keyboard.KyrgyzAlphabet

/**
 * 柯尔克孜语字符工具（纯函数，无副作用）。
 *
 * 字符集与 QWERTY 映射严格遵循：
 * - GB21669-2008《信息技术 维吾尔文、哈萨克文、柯尔克孜文编码字符集》
 * - GB/T 31917-2015《信息技术 柯尔克孜文通用键盘字母数字区布局》
 */
object KyrgyzCharacterUtils {

    /** GB/T 31917-2015 附录 A 标准柯尔克孜文字母表（30 个字母）。 */
    val ALL_LETTERS: Set<String> = KyrgyzAlphabet.LETTERS.toSet()

    /** 元音字母集合（GB 标准中的 8 个）。 */
    val VOWELS: Set<String> = setOf(
        "\u0627", // ا
        "\u06D5", // ە
        "\u06C5", // ۅ
        "\u06C7", // ۇ
        "\u06C9", // ۉ
        "\u0649", // ى
        "\u0626", // ئ
        "\u064A"  // ي
    )

    /** 辅音字母集合 = 全集 - 元音。 */
    val CONSONANTS: Set<String> = ALL_LETTERS - VOWELS

    /** 附加符号（fatha / kasra / damma / shadda）。 */
    val DIACRITICS: Set<String> = KyrgyzAlphabet.DIACRITICS.toSet()

    /** GB 标准标点符号。 */
    val PUNCTUATION: Set<String> = KyrgyzAlphabet.PUNCTUATION.toSet()

    /**
     * QWERTY 键位 -> 柯尔克孜字母 的映射（GB/T 31917-2015 表 2 标准）。
     * 与 [com.example.kyrgyzkeyboard.keyboard.KyrgyzKeyboardLayouts.DefaultLayout] 主键位一一对应。
     */
    private val QWERTY_TO_KYRGYZ: Map<Char, String> = mapOf(
        // 第 1 排 (C01-C10)
        'q' to "\u06BE", // ھ
        'w' to "\u0633", // س
        'e' to "\u062F", // د
        'r' to "\u0627", // ا
        't' to "\u06D5", // ە
        'y' to "\u0649", // ى
        'u' to "\u0642", // ق
        'i' to "\u0643", // غ
        'o' to "\u0644", // ك
        'p' to "\u061B", // ؛
        // 第 2 排 (D01-D10)
        'a' to "\u0686", // چ
        's' to "\u06CB", // ۋ
        'd' to "\u06D5", // ە
        'f' to "\u0631", // ر
        'g' to "\u062A", // ت
        'h' to "\u064A", // ي
        'j' to "\u06C7", // ۇ
        'k' to "\u06AD", // ڭ
        'l' to "\u0648", // ل
        // 第 3 排 (B01-B08 + E00)
        'z' to "\u0640", // ـ (拉长符)
        'x' to "\u0632", // ز
        'c' to "\u0634", // ش
        'v' to "\u0639", // ع
        'b' to "\u06C9", // ۉ
        'n' to "\u0628", // ب
        'm' to "\u0646", // ت
        ',' to "\u0645", // گ
        '.' to "\u060C"  // ، (逗号)
    )

    /**
     * Shift 层 QWERTY 键位映射（GB/T 31917-2015 表 2 第 2 层）。
     */
    private val QWERTY_TO_KYRGYZ_SHIFT: Map<Char, String> = mapOf(
        'r' to "\u0641", // ف
        't' to "\u06AF", // غ
        'y' to "\u062D", // ح
        'p' to "\u061F", // ؟
        'z' to "\u2026", // …
        '.' to "\u00BB"  // »
    )

    /** 单字符是否属于柯尔克孜字母表。 */
    fun isKyrgyzLetter(char: Char): Boolean =
        ALL_LETTERS.contains(char.toString())

    /** 单字符是否为元音。 */
    fun isVowel(char: Char): Boolean =
        VOWELS.contains(char.toString())

    /**
     * 阿拉伯写法文本规范化：
     * 1. 去除阿拉伯 tatweel（U+0640）拉长符
     * 2. 折叠连续空白
     * 3. 统一 Java/波斯 ي 变体到 U+06CC
     */
    fun normalizeArabicText(text: String): String {
        if (text.isEmpty()) return text
        val sb = StringBuilder(text.length)
        var lastWasSpace = false
        for (raw in text) {
            val ch = when (raw) {
                '\u0640' -> continue          // 忽略 tatweel
                '\u064A' -> '\u06CC'          // Arabic Yeh -> Farsi Yeh (统一形)
                else -> raw
            }
            if (ch.isWhitespace()) {
                if (!lastWasSpace) sb.append(' ')
                lastWasSpace = true
            } else {
                sb.append(ch)
                lastWasSpace = false
            }
        }
        return sb.toString().trim()
    }

    /**
     * 硬件键盘按键 -> 柯尔克孜字母。返回 null 表示无映射。
     * @param isShift 是否按下 Shift 键（使用第 2 层映射）
     */
    fun getKeyboardMapping(qwertyChar: Char, isShift: Boolean = false): String? {
        val lower = qwertyChar.lowercaseChar()
        return if (isShift) {
            QWERTY_TO_KYRGYZ_SHIFT[lower] ?: QWERTY_TO_KYRGYZ[lower]
        } else {
            QWERTY_TO_KYRGYZ[lower]
        }
    }
}